<!doctype html><html><head><meta charset="utf-8"><title>{{ $invoice->number }}</title><style>body{font:14px Arial;margin:35px}table{width:100%;border-collapse:collapse}th,td{border:1px solid #aaa;padding:8px}.right{text-align:right}@media print{button{display:none}}</style></head><body><button onclick="print()">Print</button><h1>Invoice {{ $invoice->number }}</h1><p>{{ data_get($invoice->company_snapshot,'name') }} · {{ data_get($invoice->company_snapshot,'email') }}</p><hr><p><strong>Bill to:</strong> {{ data_get($invoice->customer_snapshot,'name') }} · {{ data_get($invoice->customer_snapshot,'email') }}</p><p>Issued {{ $invoice->issued_at?->format('Y-m-d') }} · Due {{ $invoice->due_at?->format('Y-m-d') }} · Status {{ $invoice->status }}</p><table><thead><tr><th>Description</th><th>Qty</th><th>Unit</th><th>Total</th></tr></thead><tbody>@foreach($invoice->items as $item)<tr><td>{{ $item->description }}</td><td>{{ $item->quantity }}</td><td>{{ $item->unit_price }}</td><td>{{ $item->line_total }}</td></tr>@endforeach</tbody></table><div class="right"><h2>{{ $invoice->total }} {{ $invoice->currency_code }}</h2><p>Paid {{ $invoice->paid_total }} · Balance due {{ $invoice->balance_due }}</p></div></body></html>
